"""Generate the explicit Kotlin semantic allowlist from the reviewed source glyph registry."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
d=json.loads((ROOT/'themes/advanced-glyphs.json').read_text())
seen=set()
out='''package app.veyra.music.ui.themes

/** Generated by themes/generate_advanced_registry.py. Logos/artwork retain their identity. */
object ThemeGlyphs {
    val aliases: Map<String, String> = mapOf(\n'''
for role,names in d['aliases'].items():
 for name in names:
  assert name not in seen,name
  seen.add(name);out+=f'        "{name}" to "{role}",\n'
out+='    )\n    val advancedKeys = setOf(\n'+''.join(f'        "{k}",\n' for k in d['paths'])+'    )\n    fun key(name: String): String = aliases[name] ?: aliases[name.substringAfterLast(\'.\')] ?: name\n}\n'
(ROOT/'sharedUi/src/jvmSharedMain/kotlin/app/veyra/music/ui/themes/ThemeGlyphs.kt').write_text(out)
print(len(d['paths']),'advanced glyphs;',len(seen),'semantic aliases')
